{"task_id": "T38", "code": "def solve(nums):
    """Return length of longest strictly increasing subsequence.
    O(n log n) patience sorting.
    """
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # find position to replace (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
