def solve(grid):
    """Count islands (4-directionally connected 1s) in a possibly ragged grid.
    grid: list of list of ints (0 or 1). Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def bfs(r, c):
        from collections import deque
        dq = deque([(r, c)])
        while dq:
            i, j = dq.popleft()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore 4-directional neighbours if within bounds
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
