def solve(grid):
    """Count islands (4-directionally connected 1s) in a possibly ragged grid.
    grid: list of list of ints (0 or 1). Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def bfs(r, c):
        from collections import deque
        dq = deque([(r, c)])
        while dq:
            i, j = dq.popleft()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for di, dj in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1:
                    dq.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                islands += 1
                bfs(i, j)
    return islands

