def solve(grid):
    # Handle non-uniform row lengths and non-list inputs gracefully.
    try:
        rows = len(grid)
    except Exception:
        return 0
    if rows == 0:
        return 0
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if (i, j) in visited or grid[i][j] == 0:
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

