    # Ensure 'a' is the shorter string to minimize space
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    # DP row for previous iteration
    prev = list(range(m + 1))
    for j in range(1, n + 1):
        cur = [j] + [0] * m
        bj = b[j - 1]
        for i in range(1, m + 1):
            if a[i - 1] == bj:
                cur[i] = prev[i - 1]
            else:
                cur[i] = 1 + min(prev[i], cur[i - 1], prev[i - 1])
        prev = cur
    return prev[m]

